const nit = String($input.first().json.query.nit || '').replace(/\D/g, '');
if (!nit) {
  throw new Error('Falta el parámetro nit en la consulta.');
}
return [{ json: { nit } }];

// Consulta por partes: si el panel vuelve a preguntar trae jobId/location (solo letras, números, - y _).
const _qp = $('Webhook: consultar cupo').first().json.query || {};
const _jobId = String(_qp.jobId || '').replace(/[^A-Za-z0-9_-]/g, '');
const _location = String(_qp.location || '').replace(/[^A-Za-z0-9-]/g, '') || 'us-east1';
const nit = $input.first().json.nit;

const columnas = [
  'nit_cliente', 'razon_social', 'cupo_total', 'disponible_total',
  'nit_contraparte', 'razon_social_contraparte', 'cupo_contraparte',
  'disponible_contraparte', 'dias_mora_contraparte', 'correos_notificacion', 'vigencia'
].join(', ');

const tabla = '`inlaid-stack-375114.analytics_data_products.mapping_rules`';

const bqQuery = 'SELECT ' + columnas + ' FROM ' + tabla +
  " WHERE nit_cliente = '" + nit + "' OR nit_contraparte = '" + nit + "'";

return [{ json: { jobId: _jobId, location: _location, nit, bqQuery } }];

// Consulta por partes: BigQuery aún no termina -> el panel vuelve a preguntar con este jobId.
const _r = $input.first().json || {};
if (_r.jobComplete === false && _r.jobReference && _r.jobReference.jobId) {
  return [{ json: { pendiente: true, jobId: _r.jobReference.jobId, location: _r.jobReference.location || 'us-east1' } }];
}
const nit = $('Normalizar NIT').first().json.nit;
const resp = $input.first().json;

const fields = (resp.schema && resp.schema.fields) || [];
const rawRows = resp.rows || [];

const rows = rawRows.map(row => {
  const obj = {};
  row.f.forEach((cell, i) => {
    obj[fields[i].name] = cell.v;
  });
  return obj;
});

if (!rows.length) {
  return [{ json: { encontrado: false, mensaje: 'NIT no encontrado en BigQuery.' } }];
}

// Preferir match como contraparte (pagador); si no, usar match como cliente (emisor)
let r = rows.find(x => String(x.nit_contraparte || '').replace(/\D/g, '') === nit);
let tipo = 'contraparte';
if (!r) {
  r = rows.find(x => String(x.nit_cliente || '').replace(/\D/g, '') === nit);
  tipo = 'cliente';
}
if (!r) {
  return [{ json: { encontrado: false, mensaje: 'NIT no encontrado en BigQuery.' } }];
}

let out;
if (tipo === 'contraparte') {
  out = {
    encontrado: true,
    tipo: 'contraparte',
    nit,
    razon_social: r.razon_social_contraparte || '',
    cupo_disponible: Number(r.disponible_contraparte) || 0,
    cupo_total: Number(r.cupo_contraparte) || 0,
    dias_mora: Number(r.dias_mora_contraparte) || 0,
    correos_notificacion: r.correos_notificacion || '',
    vigencia: r.vigencia || ''
  };
} else {
  out = {
    encontrado: true,
    tipo: 'cliente',
    nit,
    razon_social: r.razon_social || '',
    cupo_disponible: Number(r.disponible_total) || 0,
    cupo_total: Number(r.cupo_total) || 0,
    dias_mora: 0
  };
}

return [{ json: out }];
